const listGuardianStudentIDs = `-- name: ListGuardianStudentIDs :many
select gr.student_id
from guardian_relationships gr
join adults a on a.id = gr.adult_id
    and a.organization_id = gr.organization_id
    and a.school_year_id = gr.school_year_id
    and a.deleted_at is null
join students s on s.id = gr.student_id
    and s.organization_id = gr.organization_id
    and s.school_year_id = gr.school_year_id
    and s.deleted_at is null
where gr.organization_id = $1
  and gr.school_year_id = $2
  and gr.adult_id = $3
order by gr.student_id
`

type ListGuardianStudentIDsParams struct {
	OrganizationID ids.XID `json:"organization_id"`
	SchoolYearID   ids.XID `json:"school_year_id"`
	AdultID        ids.XID `json:"adult_id"`
}

func (q *Queries) ListGuardianStudentIDs(ctx context.Context, arg ListGuardianStudentIDsParams) ([]ids.XID, error) {
	rows, err := q.db.Query(ctx, listGuardianStudentIDs, arg.OrganizationID, arg.SchoolYearID, arg.AdultID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ids.XID{}
	for rows.Next() {
		var student_id ids.XID
		if err := rows.Scan(&student_id); err != nil {
			return nil, err
		}
		items = append(items, student_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

